<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, action, labels, waitTask } from '../api'
import Formula from '../components/Formula.vue'
import Graph from '../components/Graph.vue'
import RecognitionReview from '../components/RecognitionReview.vue'
import DocumentUploadQueue from '../components/DocumentUploadQueue.vue'
import RelationGenerator from '../components/RelationGenerator.vue'
const route=useRoute()
const id=String(route.params.id),data=ref<any>(),tab=ref(['documents','relations','graph'].includes(String(route.query.tab))?String(route.query.tab):'knowledge'),busy=ref(false),search=ref(''),dialog=ref(''),editId=ref(''),form=reactive<any>({}),history=ref<any[]>(),duplicates=ref<any[]>([]),selectedDoc=ref('')
const uploadSection=ref<HTMLElement>(),uploader=ref<InstanceType<typeof DocumentUploadQueue>>()
let refreshTimer:ReturnType<typeof setTimeout>|undefined
function refreshDocuments(){if(refreshTimer)clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>action(load),500)}
onBeforeUnmount(()=>{if(refreshTimer)clearTimeout(refreshTimer)})
async function openUpload(){tab.value='documents';await nextTick();uploadSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}
const knowledgePage=ref(1)
watch(search,()=>knowledgePage.value=1)
const recognitionDoc=ref(''),parseMode=ref('auto'),pageStart=ref(1),pageEnd=ref<number>()
const splitMethod=ref('semantic'),chunkSize=ref(1200),overlap=ref(0),splitModel=ref(''),models=ref<any[]>([]),splitReport=ref<any>()
const splitMethods=[{id:'document',name:'整篇文档'},{id:'page',name:'按页 / 幻灯片'},{id:'paragraph',name:'按段落 / OCR 内容块'},{id:'fixed',name:'固定字符长度'},{id:'recursive',name:'递归文本切分'},{id:'semantic',name:'模型语义切分'}]
function splittingOptions(){return {method:splitMethod.value,chunk_size:chunkSize.value,overlap:['fixed','recursive'].includes(splitMethod.value)?overlap.value:0,model_profile_id:splitMethod.value==='semantic'?splitModel.value||null:null}}
async function inspectSplitting(key:string){await action(async()=>splitReport.value=await api(`/admin/documents/${key}/splitting`))}
function parseOptions(){return {mode:parseMode.value,page_start:pageStart.value,page_end:pageEnd.value||null,splitting:splittingOptions()}}
async function reprocess(key:string){await action(async()=>{const task=await api(`/admin/knowledge-bases/${id}/documents/${key}/reprocess`,'POST',parseOptions());ElMessage.info('解析与切分任务已提交，可在任务中心查看进度');await waitTask(task);await load()})}
function editRecognized(locator:string){const node=nodes.value.find((n:any)=>n.sources.some((s:any)=>s.document_id===recognitionDoc.value&&s.locator===locator));if(node){recognitionDoc.value='';editKnowledge(node)}}
const nodes=computed(()=>data.value?.knowledge.filter((n:any)=>!n.withdrawn)||[])
const filtered=computed(()=>nodes.value.filter((n:any)=>(n.title.includes(search.value)||n.content.includes(search.value))))
const edges=computed(()=>data.value?.relations.filter((n:any)=>!n.withdrawn)||[])
const questions=computed(()=>data.value?.questions.filter((n:any)=>!n.withdrawn)||[])
async function load(){data.value=await api('/admin/knowledge-bases/'+id+'/contents')}
onMounted(()=>action(async()=>{await load();models.value=(await api('/admin/model-profiles')).filter((m:any)=>m.purpose==='generation'&&m.provider!=='demo');splitModel.value=models.value.find((m:any)=>m.id===data.value.kb.extraction_profile_id)?.id||models.value.find((m:any)=>m.name==='ds-flash')?.id||models.value[0]?.id||''}))
function editKnowledge(n?:any){editId.value=n?.id||'';Object.assign(form,{kind:n?.kind||'concept',title:n?.title||'',content:n?.content||'',chapter:n?.attributes.chapter||'',latex:n?.attributes.latex||'',conditions:n?.attributes.conditions||'',aliases:(n?.attributes.aliases||[]).join('、'),document_id:n?.sources[0]?.document_id||'',locator:n?.sources[0]?.locator||'人工整理',excerpt:n?.sources[0]?.excerpt||'',note:n?.sources[0]?.note||'',change_note:'人工编辑',originalSource:n?.sources[0]||{},extraSources:n?.sources.slice(1)||[],originalAttributes:n?.attributes||{}});dialog.value='knowledge'}
function editRelation(r?:any){editId.value=r?.id||'';Object.assign(form,{source_id:r?.source_id||'',target_id:r?.target_id||'',kind:r?.kind||'prerequisite'});dialog.value='relations'}
function editQuestion(q?:any){editId.value=q?.id||'';Object.assign(form,{title:q?.title||'',kind:q?.kind||'expression',answer:q?.answer||'',explanation:q?.explanation||'',knowledge_ids:q?.knowledge_ids||[],difficulty:q?.attributes.difficulty||'medium',assumption:q?.attributes.assumption||'real',chapter:q?.attributes.chapter||'',options:q?.attributes.options||'',tolerance:q?.attributes.tolerance||.000001,past_exam:q?.attributes.past_exam||false,originalAttributes:q?.attributes||{}});dialog.value='questions'}
async function save(){busy.value=true;await action(async()=>{let payload:any;if(dialog.value==='knowledge')payload={kind:form.kind,title:form.title,content:form.content,attributes:{...form.originalAttributes,chapter:form.chapter,latex:form.latex,conditions:form.conditions,aliases:form.aliases.split(/[、,，]/).map((s:string)=>s.trim()).filter(Boolean)},sources:[{...(form.originalSource.document_id===form.document_id?form.originalSource:{}),document_id:form.document_id||null,locator:form.locator,excerpt:form.excerpt,note:form.note},...form.extraSources],change_note:form.change_note};else if(dialog.value==='relations')payload={source_id:form.source_id,target_id:form.target_id,kind:form.kind};else payload={title:form.title,kind:form.kind,answer:form.answer,explanation:form.explanation,knowledge_ids:form.knowledge_ids,attributes:{...form.originalAttributes,chapter:form.chapter,difficulty:form.difficulty,assumption:form.assumption,options:form.options,tolerance:form.tolerance,past_exam:form.past_exam}};await api(`/admin/knowledge-bases/${id}/${dialog.value}`+(editId.value?'/'+editId.value:''),editId.value?'PUT':'POST',payload);dialog.value='';await load();ElMessage.success('已保存；发布后应用使用新版本')});busy.value=false}
async function withdraw(resource:string,key:string){try{await ElMessageBox.confirm('撤回后新请求立即停止使用该内容，关联题目和关系也会撤回。','撤回内容',{type:'warning'});await action(async()=>{await api(`/admin/knowledge-bases/${id}/${resource}/${key}`,'DELETE');await load()})}catch{}}
async function publish(){busy.value=true;await action(async()=>{await waitTask(await api(`/admin/knowledge-bases/${id}/publish`,'POST'));await load();ElMessage.success('发布成功，已同步应用检索索引')});busy.value=false}
async function inspectHistory(key:string){await action(async()=>history.value=await api('/admin/audit/'+key))}
async function scanDuplicates(){await action(async()=>{duplicates.value=await api(`/admin/knowledge-bases/${id}/duplicates`);if(!duplicates.value.length)ElMessage.info('未发现相似名称候选')})}
async function merge(a:string,b:string){try{await ElMessageBox.confirm('请确认两个名称确实指同一概念。合并后发布版本即可更新应用中的知识和关系。','人工确认合并');await action(async()=>{await api(`/admin/knowledge-bases/${id}/merge`,'POST',{canonical_id:a,duplicate_ids:[b]});await load();await scanDuplicates()})}catch{}}
const templateText=ref(''),templateOpen=ref(false)
async function templateGenerate(){await action(async()=>{await api(`/admin/knowledge-bases/${id}/templates/generate`,'POST',JSON.parse(templateText.value));templateOpen.value=false;await load();ElMessage.success('题目已生成，可直接发布')})}
function templateExample(){templateText.value=JSON.stringify({question:{title:'计算 d(x^{{n}})/dx，设 x>0。',kind:'expression',answer:'{{n}}*x^({{n}}-1)',explanation:'使用幂函数求导公式。',knowledge_ids:nodes.value.length?[nodes.value[0].id]:[],attributes:{assumption:'positive',difficulty:'easy'}},parameters:{n:[2,3,4,5]},count:4},null,2);templateOpen.value=true}
</script>
<template><section class="page" v-if="data"><router-link to="/admin/knowledge-bases" class="text-link">← 返回知识库</router-link><div class="page-title spaced"><div><h1>{{data.kb.name}}</h1><p class="muted">{{data.kb.description}}</p></div><div class="knowledge-actions"><el-button type="primary" @click="openUpload">上传资料</el-button><el-button :loading="busy" @click="publish">发布版本</el-button></div></div><div class="kb-stats"><div><strong>{{nodes.length}}</strong><span>知识条目</span></div><div><strong>{{edges.length}}</strong><span>知识关系</span></div><div><strong>{{questions.length}}</strong><span>练习题目</span></div><div><strong>{{data.releases.length}}</strong><span>发布版本</span></div></div><el-alert title="资料导入或内容保存后可直接发布。发布成功后，应用使用新的知识版本。" type="info" :closable="false"/><el-tabs v-model="tab" class="spaced"><el-tab-pane name="knowledge" label="知识整理"/><el-tab-pane name="documents" label="原始资料"/><el-tab-pane name="relations" label="知识关系"/><el-tab-pane name="questions" label="练习题库"/><el-tab-pane name="graph" label="知识图谱"/><el-tab-pane name="versions" label="发布历史"/></el-tabs>
<template v-if="tab==='knowledge'"><div class="toolbar"><el-input v-model="search" placeholder="搜索知识标题或内容" clearable/><el-button @click="scanDuplicates">检查重复候选</el-button><el-button type="primary" @click="editKnowledge()">＋ 添加知识</el-button></div><div v-for="d in duplicates" :key="d.a+d.b" class="duplicate-row"><span>候选：{{d.title_a}} ↔ {{d.title_b}} · 相似度 {{Math.round(d.score*100)}}%</span><el-button size="small" @click="merge(d.a,d.b)">人工确认合并</el-button></div><el-table :data="filtered.slice((knowledgePage-1)*100,knowledgePage*100)" class="panel"><el-table-column label="知识" min-width="240"><template #default="{row}"><b class="clickable" @click="editKnowledge(row)">{{row.title}}</b><div class="muted small">{{row.attributes.chapter}} · {{row.sources.length}} 个来源块</div><el-tag v-if="row.attributes.splitting" size="small" :type="row.attributes.splitting.method==='semantic'?'success':'info'">{{splitMethods.find(m=>m.id===row.attributes.splitting.method)?.name}} {{row.attributes.splitting.model||''}}</el-tag></template></el-table-column><el-table-column label="类型" width="95"><template #default="{row}">{{labels[row.kind]}}</template></el-table-column><el-table-column label="来源" min-width="140"><template #default="{row}">{{row.sources[0]?.locator}}</template></el-table-column><el-table-column label="操作" min-width="355"><template #default="{row}"><el-button size="small" @click="editKnowledge(row)">编辑</el-button><el-button size="small" @click="inspectHistory(row.id)">记录</el-button><el-button size="small" @click="withdraw('knowledge',row.id)">撤回</el-button></template></el-table-column></el-table><el-pagination class="spaced" v-model:current-page="knowledgePage" :page-size="100" :total="filtered.length" layout="total, prev, pager, next"/></template>
<section v-show="tab==='documents'" ref="uploadSection" class="document-upload-section"><div class="panel parser-settings"><div class="section-heading"><div><h2>上传资料</h2></div><el-button type="primary" @click="uploader?.selectFiles()">选择文件（可多选）</el-button></div><p class="muted">先确认下方切分方式与模型，再一次选择多份文件。每份资料独立处理，单个文件失败不会中断其余文件。</p><b>解析与知识切分设置</b><div class="inline-form spaced"><el-tag>PDF / 图片 → PaddleOCR · 其他文档 → 本地解析</el-tag><label>PDF 起始页 <el-input-number v-model="pageStart" :min="1"/></label><label>结束页 <el-input-number v-model="pageEnd" :min="pageStart" placeholder="留空至末页"/></label></div><div class="inline-form spaced"><label>切分方法 <el-select v-model="splitMethod" aria-label="切分方法"><el-option v-for="m in splitMethods" :key="m.id" :label="m.name" :value="m.id"/></el-select></label><label v-if="['fixed','recursive','semantic'].includes(splitMethod)">{{splitMethod==='semantic'?'目标字符数（以语义完整为先）':'片段字符数'}} <el-input-number v-model="chunkSize" :min="100" :max="24000" :step="100"/></label><label v-if="['fixed','recursive'].includes(splitMethod)">重叠字符数 <el-input-number v-model="overlap" :min="0" :max="Math.min(chunkSize-1,4000)"/></label><label v-if="splitMethod==='semantic'">语义切分模型 <el-select v-model="splitModel" placeholder="选择生成模型" aria-label="语义切分模型"><el-option v-for="m in models" :key="m.id" :value="m.id" :label="`${m.name} · ${m.model}`"/></el-select></label></div><p class="muted">{{splitMethod==='semantic'?'由所选模型判断语义边界和知识类型，可合并跨页的条件、公式与解答。原文不改写，失败不会降级为普通切分。':'程序按所选规则切分，不调用生成模型；这不是语义知识提取。'}} {{splitMethod==='document'?'整篇上限 30,000 字符 / 256 个来源块，长文请使用其他方式。':''}} {{splitMethod==='fixed'?'固定长度可能截断公式，数学资料建议使用语义或递归切分。':''}}</p><p class="muted">PDF 和图片将发送到已配置的 PaddleOCR 云端；页码范围在上传前截取。公式输出 LaTeX，图片与原文位置保留供校对。DOCX/PPTX 默认仅提取文字，图文识别请先导出 PDF。</p></div><DocumentUploadQueue ref="uploader" :kb-id="id" :options="parseOptions()" :settings-label="`${splitMethods.find(m=>m.id===splitMethod)?.name}${splitMethod==='semantic'?' · '+(models.find(m=>m.id===splitModel)?.name||'未选择模型'):''} · PDF ${pageStart}—${pageEnd||'末'}页`" @changed="refreshDocuments"/><el-table :data="data.documents.filter((d:any)=>!d.withdrawn)" class="panel"><el-table-column prop="filename" label="文档" min-width="240"/><el-table-column label="处理状态" width="140"><template #default="{row}">{{['ready','review'].includes(row.state)?'已导入':labels[row.state]||'已上传'}}</template></el-table-column><el-table-column label="切分方法" min-width="150"><template #default="{row}">{{splitMethods.find(m=>m.id===row.parse_options?.splitting?.method)?.name||'旧版原文分块'}}<div class="muted small">{{row.recognition?.splitting?.model_name||''}}</div></template></el-table-column><el-table-column label="操作" min-width="330"><template #default="{row}"><el-button size="small" @click="selectedDoc=row.id">原文对照</el-button><el-button v-if="row.recognition?.parser" size="small" @click="recognitionDoc=row.id">识别校对</el-button><el-button v-if="row.recognition?.splitting" size="small" @click="inspectSplitting(row.id)">切分报告</el-button><el-button size="small" @click="reprocess(row.id)">重新解析切分</el-button><el-button size="small" @click="withdraw('documents',row.id)">撤回文档</el-button></template></el-table-column></el-table></section>
<section v-show="tab==='relations'"><RelationGenerator :kb-id="id" :models="models" :default-model="models.find(m=>m.name==='ds-flash')?.id||splitModel" :knowledge-count="nodes.length" @changed="load"/><div class="toolbar"><p class="muted">前置关系方向：先学的知识 → 后学的知识。发布时检查循环。</p><el-button type="primary" @click="editRelation()">＋ 添加关系</el-button></div><el-table :data="edges" class="panel"><el-table-column type="expand"><template #default="{row}"><div class="relation-evidence"><template v-if="row.attributes?.origin==='model'"><p><b>生成依据：</b>{{row.attributes.reason}}</p><p v-for="e in row.attributes.evidence" :key="e.knowledge_id"><b>{{nodes.find((n:any)=>n.id===e.knowledge_id)?.title}}（知识版本 {{e.revision}}）</b><br/>{{e.quote}}</p></template><p v-else>人工维护的关系</p><el-button size="small" @click="inspectHistory(row.id)">查看修改记录</el-button></div></template></el-table-column><el-table-column label="起点" min-width="180"><template #default="{row}">{{nodes.find((n:any)=>n.id===row.source_id)?.title}}</template></el-table-column><el-table-column label="关系" width="140"><template #default="{row}">{{labels[row.kind]}}</template></el-table-column><el-table-column label="终点" min-width="180"><template #default="{row}">{{nodes.find((n:any)=>n.id===row.target_id)?.title}}</template></el-table-column><el-table-column label="生成方式" min-width="150"><template #default="{row}"><el-tag v-if="row.attributes?.origin==='model'" type="success">{{row.attributes.model_name}}</el-tag><span v-else class="muted">人工维护</span></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button size="small" @click="editRelation(row)">编辑</el-button><el-button size="small" @click="withdraw('relations',row.id)">撤回</el-button></template></el-table-column></el-table></section>
<section v-if="tab==='questions'"><div class="toolbar"><p class="muted">表达式使用 x^2、sin(x) 等输入。证明题不自动判分。</p><el-button @click="templateExample">参数化出题</el-button><el-button type="primary" @click="editQuestion()">＋ 添加题目</el-button></div><el-table :data="questions" class="panel"><el-table-column prop="title" label="题干" min-width="270"/><el-table-column label="类型" width="125"><template #default="{row}">{{labels[row.kind]}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button size="small" @click="editQuestion(row)">编辑</el-button><el-button size="small" @click="withdraw('questions',row.id)">撤回</el-button></template></el-table-column></el-table></section>
<div v-if="tab==='graph'" class="panel"><div class="toolbar"><p class="muted">使用图数据库工作台分页浏览节点、来源、邻域和发布索引。</p><router-link :to="{path:'/admin/graph',query:{kb_id:id}}"><el-button type="primary">打开图数据库工作台 ↗</el-button></router-link></div><Graph v-if="nodes.length<=200" :nodes="nodes" :edges="edges" @select="(key:string)=>editKnowledge(nodes.find((n:any)=>n.id===key))"/><el-empty v-else description="当前知识较多，请进入工作台筛选或分页查看"/></div>
<el-table v-if="tab==='versions'" :data="data.releases" class="panel"><el-table-column label="版本" prop="revision" width="100"/><el-table-column label="标识" prop="id" min-width="260"/><el-table-column label="内容" min-width="200"><template #default="{row}">{{row.snapshot.nodes.length}} 条知识 / {{row.snapshot.edges.length}} 条关系 / {{row.snapshot.questions.length}} 道题</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag v-if="row.id===data.kb.current_release_id" type="success">当前发布</el-tag><span v-else class="muted">历史快照</span></template></el-table-column></el-table>
<el-drawer :model-value="!!dialog" :title="dialog==='knowledge'?'知识编辑':dialog==='relations'?'编辑知识关系':'编辑练习题'" size="min(680px, 96vw)" @close="dialog=''"><el-form label-position="top"><template v-if="dialog==='knowledge'"><div class="inline-form"><el-form-item label="类型"><el-select v-model="form.kind"><el-option v-for="k in ['concept','theorem','formula','example','note']" :key="k" :label="labels[k]" :value="k"/></el-select></el-form-item><el-form-item label="所属章节"><el-input v-model="form.chapter"/></el-form-item></div><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="知识正文"><el-input v-model="form.content" type="textarea" :rows="6"/></el-form-item><el-form-item label="公式（LaTeX）"><el-input v-model="form.latex" type="textarea" :rows="2"/></el-form-item><Formula v-if="form.latex" :value="form.latex" block/><el-form-item label="适用条件与定义域"><el-input v-model="form.conditions" type="textarea"/></el-form-item><el-form-item label="别名（顿号分隔）"><el-input v-model="form.aliases"/></el-form-item><h3>来源与对照</h3><img v-if="form.originalSource.asset_id" class="recognition-image" :src="`/api/admin/documents/${form.originalSource.document_id}/assets/${form.originalSource.asset_id}`" alt="对应公式或文字的原图"/><p v-for="w in form.originalSource.warnings||[]" :key="w" class="recognition-warning">{{w}}</p><el-form-item label="来源文档"><el-select v-model="form.document_id" clearable class="full-width" placeholder="人工补充知识可不选文件"><el-option v-for="d in data.documents.filter((d:any)=>!d.withdrawn)" :key="d.id" :value="d.id" :label="d.filename"/></el-select><el-button v-if="form.document_id" text @click="selectedDoc=form.document_id">打开原文 ↗</el-button></el-form-item><el-form-item label="页码 / 幻灯片 / 章节定位"><el-input v-model="form.locator"/></el-form-item><el-form-item label="原文片段"><el-input v-model="form.excerpt" type="textarea" :rows="5"/></el-form-item><el-collapse v-if="form.extraSources?.length"><el-collapse-item :title="`另外 ${form.extraSources.length} 个原文来源（跨块 / 跨页）`"><article v-for="(source,index) in form.extraSources" :key="index"><b>{{source.locator}}</b><img v-if="source.asset_id" class="recognition-image" :src="`/api/admin/documents/${source.document_id}/assets/${source.asset_id}`" alt="原文块"/><pre style="white-space:pre-wrap">{{source.excerpt}}</pre></article></el-collapse-item></el-collapse><el-form-item label="来源说明或校正依据"><el-input v-model="form.note" type="textarea" placeholder="人工知识必须填写来源说明；修正公式时请说明依据"/></el-form-item><el-form-item label="本次修改说明"><el-input v-model="form.change_note"/></el-form-item></template>
<template v-else-if="dialog==='relations'"><el-form-item label="起点知识"><el-select v-model="form.source_id" filterable class="full-width"><el-option v-for="n in nodes" :key="n.id" :value="n.id" :label="n.title"/></el-select></el-form-item><el-form-item label="关系类型"><el-select v-model="form.kind" class="full-width"><el-option v-for="r in ['prerequisite','uses_theorem','uses_formula','assesses','confusable','related']" :key="r" :value="r" :label="labels[r]"/></el-select></el-form-item><el-form-item label="终点知识"><el-select v-model="form.target_id" filterable class="full-width"><el-option v-for="n in nodes" :key="n.id" :value="n.id" :label="n.title"/></el-select></el-form-item></template>
<template v-else><el-form-item label="题型"><el-select v-model="form.kind" class="full-width"><el-option v-for="k in ['choice','numeric','expression','antiderivative','proof']" :key="k" :value="k" :label="labels[k]"/></el-select></el-form-item><el-form-item label="题干"><el-input v-model="form.title" type="textarea" :rows="3"/></el-form-item><el-form-item v-if="form.kind==='choice'" label="选项"><el-input v-model="form.options" type="textarea"/></el-form-item><el-form-item label="参考答案"><el-input v-model="form.answer" type="textarea" :rows="2"/></el-form-item><el-form-item label="解答与依据"><el-input v-model="form.explanation" type="textarea" :rows="4"/></el-form-item><el-form-item label="考查知识点"><el-select v-model="form.knowledge_ids" multiple filterable class="full-width"><el-option v-for="n in nodes" :key="n.id" :value="n.id" :label="n.title"/></el-select></el-form-item><div class="inline-form"><el-form-item label="难度"><el-select v-model="form.difficulty"><el-option v-for="d in ['easy','medium','hard']" :key="d" :value="d" :label="labels[d]"/></el-select></el-form-item><el-form-item label="变量条件"><el-select v-model="form.assumption"><el-option label="x 为实数" value="real"/><el-option label="x > 0" value="positive"/><el-option label="x < 0" value="negative"/></el-select></el-form-item></div><el-form-item label="所属章节"><el-input v-model="form.chapter"/></el-form-item><el-form-item v-if="form.kind==='numeric'" label="数值容差"><el-input-number v-model="form.tolerance" :min="0" :step=".000001" :precision="6"/></el-form-item><el-checkbox v-model="form.past_exam">往年试题（用于复习优先级统计）</el-checkbox></template></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-drawer>
<el-dialog :model-value="!!selectedDoc" title="原始资料对照" width="92vw" @close="selectedDoc=''"><iframe v-if="selectedDoc" :src="'/api/admin/documents/'+selectedDoc+'/file'" class="document-preview" title="原始文件预览"></iframe></el-dialog>
<el-drawer :model-value="!!history" title="修改记录与差异" size="min(700px, 96vw)" @close="history=undefined"><article v-for="h in history" :key="h.id" class="audit-entry"><b>{{h.action}}</b><div class="audit-diff"><section><small>修改前</small><pre>{{JSON.stringify(h.before,null,2)}}</pre></section><section><small>修改后</small><pre>{{JSON.stringify(h.after,null,2)}}</pre></section></div></article><el-empty v-if="!history?.length" description="暂无人工修改记录"/></el-drawer>
<el-dialog v-model="templateOpen" title="参数化题目模板" width="min(760px, 96vw)"><p>使用双大括号参数生成变式题目。知识点 ID 已填入示例，可在知识列表中选择对应题目后调整。</p><el-input v-model="templateText" type="textarea" :rows="20"/><template #footer><el-button type="primary" @click="templateGenerate">生成题目</el-button></template></el-dialog>
<el-dialog :model-value="!!splitReport" title="切分报告" width="min(680px,96vw)" @close="splitReport=undefined"><template v-if="splitReport?.report"><el-descriptions :column="1" border><el-descriptions-item label="方法">{{splitMethods.find(m=>m.id===splitReport.report.method)?.name}}</el-descriptions-item><el-descriptions-item label="模型">{{splitReport.report.model_name||'程序规则'}} {{splitReport.report.model||''}}</el-descriptions-item><el-descriptions-item label="输入 → 输出">{{splitReport.report.input_blocks}} 个原文块 → {{splitReport.report.chunk_count}} 个片段</el-descriptions-item><el-descriptions-item label="原文覆盖">{{splitReport.report.coverage*100}}% · 正文不改写</el-descriptions-item><el-descriptions-item label="本次模型调用 / 缓存复用">{{splitReport.report.calls}} / {{splitReport.report.cache_hits||0}}</el-descriptions-item><el-descriptions-item label="处理说明">{{splitReport.report.method==='semantic'?'已做模型语义切分和知识类型标注；可在「知识关系」页使用模型生成关系。':'仅做规则切分；没有进行模型语义提取。'}} 可对照原图编辑内容，保存后直接发布。</el-descriptions-item></el-descriptions></template></el-dialog>
<RecognitionReview v-if="recognitionDoc" :document-id="recognitionDoc" @close="recognitionDoc=''" @edit="editRecognized"/></section></template>

